// This is used to tile the j-loop with into_blocks_dynamic, improving
// cache/TLB behavior for large N while still handling non-multiple sizes.
constexpr std::size_t GESUMMV_J_BLOCK = 128;

[[gnu::flatten, gnu::noinline]]
void kernel_gesummv(num_t alpha, num_t beta, auto A, auto B, auto tmp, auto x, auto y) {
	using namespace noarr;

	// Original C:
	// for (i = 0; i < _PB_N; i++) {
	//   tmp[i] = 0.0;
	//   y[i] = 0.0;
	//   for (j = 0; j < _PB_N; j++) {
	//     tmp[i] = A[i][j] * x[j] + tmp[i];
	//     y[i]   = B[i][j] * x[j] + y[i];
	//   }
	//   y[i] = alpha * tmp[i] + beta * y[i];
	// }
	//
	// Optimizations applied:
	//   1. Per-row accumulators (tmp_i, y_i_acc) are kept in registers.
	//      We only write tmp[i] and y[i] once per row instead of in every
	//      iteration of the inner loop. This dramatically reduces memory
	//      traffic and exposes a clean reduction pattern to the compiler,
	//      enabling vectorization.
	//
	//   2. The inner 'j' dimension is tiled with into_blocks_dynamic. We
	//      split 'j' into:
	//         - 'J' : block index
	//         - 'j' : index within the block
	//         - 'p' : presence flag (length 0 or 1), automatically ensuring
	//                correctness even when N is not a multiple of the block
	//                size. We then hoist 'J' to be the outermost inner
	//                dimension, so each row is traversed block by block.
	//
	//      The traversal states produced by this blocked traverser still
	//      contain the original indices 'i' and 'j', and the extra indices
	//      ('J', 'p') are ignored when indexing A, B, and x. Thus the
	//      numerical result is identical to the simple nested loops, with
	//      only a different (but associative) accumulation order.

	#pragma scop
	traverser(A, B, x).template for_dims<'i'>([&](auto inner_row) {
		// inner_row has 'i' fixed, 'j' remaining (via A and B; x only has 'j')
		auto si = inner_row.state(); // state with fixed 'i'

		// Accumulators kept in registers for this row i
		num_t tmp_i   = (num_t)0.0;
		num_t y_i_acc = (num_t)0.0;

		// Tile the 'j' dimension for better cache behavior.
		// into_blocks_dynamic<'j','J','j','p'>(...) produces a view where:
		//   - 'J' is the block index in 'j'
		//   - inner 'j' is the index within the block
		//   - 'p' is a presence dimension that is empty for (J,j) pairs that
		//     map beyond the original length in 'j'
		// hoist<'J'> makes 'J' the outer dimension of the inner traversal.
		auto inner_blocked = inner_row.order(
			noarr::into_blocks_dynamic<'j', 'J', 'j', 'p'>(GESUMMV_J_BLOCK)
			^ noarr::hoist<'J'>()
		);

		inner_blocked.for_each([&](auto s_block) {
			// s_block contains indices for:
			//   - 'i' : row
			//   - 'j' : column within the matrix
			//   - 'J' and 'p' : blocking / presence (ignored by A, B, x)
			//
			// Accessing x with s_block is valid: x only uses 'j' and ignores
			// all other indices present in the state.
			const num_t xj = x[s_block];

			tmp_i   += A[s_block] * xj;
			y_i_acc += B[s_block] * xj;
		});

		// Store the final results for this row.
		// tmp[i] matches the classical temporary array in the original code.
		tmp[si] = tmp_i;
		y[si]   = alpha * tmp_i + beta * y_i_acc;
	});
	#pragma endscop
