	trav.template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed; state() only carries the original dimensions.
		auto si = trav_i.state(); // contains index in 'i' only
		// We'll use si to access tmp[i] and y[i] once per row.

