			trav_block.for_each([&](auto s) {
				// s has both 'i' and 'j' (original dimensions).
				auto j  = get_index<'j'>(s);
				auto sj = idx<'j'>(j);

				const num_t xj = x[sj];

				// Accumulate contributions in registers instead of
				// repeatedly loading/storing tmp[i], y[i].
				acc_Ax += A[s] * xj;
				acc_Bx += B[s] * xj;
			});
		});

