constexpr auto y_layout   = i_vec;         // length N, indexed by 'i'

// -----------------------------------------------------------------------------
// Initialization
// -----------------------------------------------------------------------------

// initialization function
void init_array(num_t &alpha, num_t &beta, auto A, auto B, auto x) {
	using namespace noarr;

	// matrices are N x N
	auto n = A | get_length<'i'>();

	alpha = static_cast<num_t>(1.5);
	beta  = static_cast<num_t>(1.2);

	// Precompute reciprocal of n to replace divisions by a cheaper multiply
	const num_t inv_n = static_cast<num_t>(1.0) / static_cast<num_t>(n);

	// Original C:
	// for (i = 0; i < n; i++) {
	//   x[i] = (DATA_TYPE)( i % n) / n;
	//   for (j = 0; j < n; j++) {
	//     A[i][j] = (DATA_TYPE)((i*j+1) % n) / n;
	//     B[i][j] = (DATA_TYPE)((i*j+2) % n) / n;
	//   }
	// }

	// We iterate over rows i, and inside over columns j. This preserves the
	// original access pattern (row-major) while avoiding any explicit loops
	// and relying on noarr traversers.
	traverser(A, B).template for_dims<'i'>([&](auto inner) {
		// inner has 'i' fixed, 'j' remaining
		auto si = inner.state(); // contains index in 'i'
		auto i  = get_index<'i'>(si);

		// x[i] — x is indexed by 'j', so we use j = i
		// Note: i < n, so (i % n) == i; we keep the modulo to mirror the original
		x[idx<'j'>(i)] = static_cast<num_t>(i % n) * inv_n;

		// Initialize A[i][j] and B[i][j] for this fixed i
		inner.for_each([&](auto s) {
			auto j = get_index<'j'>(s);

			// Arithmetic is done in integer domain and only then scaled by 1/n
			const auto a_ij = ( (i * j + 1) % n );
			const auto b_ij = ( (i * j + 2) % n );

			A[s] = static_cast<num_t>(a_ij) * inv_n;
			B[s] = static_cast<num_t>(b_ij) * inv_n;
		});
	});
}

