	using namespace noarr;

	// Tunable parameter: length of a potential 'j' block.  Not used directly in
	// this version, but serves as a single place to adjust if one wants to
	// experiment with tiling via noarr::into_blocks for specific hardware.
	constexpr std::size_t j_block_size = 256;
	(void)j_block_size; // silence unused-variable warning for now

	// Original C:
	// for (i = 0; i < _PB_N; i++) {
	//   tmp[i] = 0.0;
	//   y[i]   = 0.0;
	//   for (j = 0; j < _PB_N; j++) {
	//     tmp[i] = A[i][j] * x[j] + tmp[i];
	//     y[i]   = B[i][j] * x[j] + y[i];
	//   }
	//   y[i] = alpha * tmp[i] + beta * y[i];
	// }

	#pragma scop
	traverser(A, B, tmp, x, y).template for_dims<'i'>([&](auto inner) {
		// inner has 'i' fixed, 'j' remaining
		auto si = inner.state(); // state with fixed 'i'

		// Keep row-wise accumulators in registers to minimize traffic
		num_t tmp_acc = static_cast<num_t>(0.0);
		num_t y_acc   = static_cast<num_t>(0.0);

		// Accumulate over j for the current row i
		inner.for_each([&](auto s) {
			// s has both 'i' and 'j'
			// x is indexed only by 'j', so the 'i' present in s is ignored
			const num_t xj = x[s];

			tmp_acc += A[s] * xj;
			y_acc   += B[s] * xj;
		});

		// Store final row results once
		tmp[si] = tmp_acc;
		y[si]   = alpha * tmp_acc + beta * y_acc;
	});
	#pragma endscop
}

} // namespace

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------

