// computation kernel
// -----------------------------------------------------------------------------
//
// Optimized GESUMMV kernel:
//
//  tmp[i] = sum_j A[i][j] * x[j]
//  y[i]   = alpha * tmp[i] + beta * sum_j B[i][j] * x[j]
//
// Optimizations compared to the original version:
//   - The work is logically split into three traversals:
//       1) zero-initialize tmp[] and y[]
//       2) accumulate the matrix-vector products into tmp[] and y[]
//       3) apply the linear combination y[i] = alpha*tmp[i] + beta*y[i]
//     This keeps the inner loops free of redundant scalar operations.
//   - In the accumulation phase we keep references to tmp[i] and y[i]
//     (or tmp[i], y[i] pairs) so their address computation happens once
//     per i, not once per j. This is important because Noarr indexing
//     involves structure logic, and the compiler is more likely to keep
//     these references in registers.
//   - x[j] is accessed as x[state] directly. The state carries both 'i'
//     and 'j', but the 1D x-structure only uses 'j' and ignores 'i',
//     avoiding extra index construction.
//   - Traversal order is selectable at compile time via gesummv_j_outer:
//       * false (default): i-major (row-wise) traversal
//       * true:  j-major (column-wise) traversal
//     This makes it possible to tune for different layouts / platforms
//     without touching the rest of the code.
//
// All loop nests are expressed using Noarr traversers (for_each / for_dims).
//
[[gnu::flatten, gnu::noinline]]
void kernel_gesummv(num_t alpha, num_t beta, auto A, auto B, auto tmp, auto x, auto y) {
	using namespace noarr;

	// Original C:
	// for (i = 0; i < _PB_N; i++) {
	//   tmp[i] = 0.0;
	//   y[i] = 0.0;
	//   for (j = 0; j < _PB_N; j++) {
	//     tmp[i] = A[i][j] * x[j] + tmp[i];
	//     y[i]   = B[i][j] * x[j] + y[i];
	//   }
	//   y[i] = alpha * tmp[i] + beta * y[i];
	// }

	#pragma scop

	// ---------------------------------------------------------------------
	// 1) Zero-initialize tmp[i] and y[i]
	// ---------------------------------------------------------------------
	traverser(tmp, y).for_each([&](auto s_i) {
		tmp[s_i] = (num_t)0.0;
		y[s_i]   = (num_t)0.0;
	});

	// ---------------------------------------------------------------------
	// 2) Accumulate matrix-vector products into tmp[i] and y[i]
	// ---------------------------------------------------------------------
	if constexpr (gesummv_j_outer) {
		// Column-major style: outer loop over j, inner over i.
		// This can be beneficial if the layout (or another implementation)
		// uses 'j'-major storage, or if we want better x[j] reuse across i.
		traverser(A, B, x, tmp, y).template for_dims<'j'>([&](auto trav_j) {
			// trav_j has 'j' fixed, 'i' remaining
			auto s_j   = trav_j.state();  // contains index in 'j'
			const num_t x_j = x[s_j];     // x is 1D (indexed by 'j')

			// Iterate all i for this fixed j
			trav_j.template for_dims<'i'>([&](auto trav_ij) {
				// trav_ij has both 'i' and 'j' fixed
				auto s_ij = trav_ij.state(); // contains 'i' and 'j'

				// References into row vectors tmp[i] and y[i]
				auto &tmp_i = tmp[s_ij]; // 'j' is ignored by tmp-structure
				auto &y_i   = y[s_ij];

				tmp_i += A[s_ij] * x_j;
				y_i   += B[s_ij] * x_j;
			});
		});
	} else {
		// Row-major style: outer loop over i, inner over j.
		// This matches the row-major layout mat_layout and
		// results in contiguous accesses along 'j'.
		traverser(A, B, x, tmp, y).template for_dims<'i'>([&](auto trav_i) {
			// trav_i has 'i' fixed, 'j' remaining
			auto s_i = trav_i.state(); // contains index in 'i'

			// tmp[i] and y[i] accessed through references so that
			// their address / offset is computed once per row.
			auto &tmp_i = tmp[s_i];
			auto &y_i   = y[s_i];

			// Iterate all j for this fixed i
			trav_i.for_each([&](auto s_ij) {
				// s_ij has both 'i' and 'j'
				const num_t x_j = x[s_ij]; // 'i' is ignored by x-structure

				tmp_i += A[s_ij] * x_j;
				y_i   += B[s_ij] * x_j;
			});
		});
	}

	// ---------------------------------------------------------------------
	// 3) Apply linear combination y[i] = alpha * tmp[i] + beta * y[i]
	// ---------------------------------------------------------------------
	traverser(tmp, y).template for_dims<'i'>([&](auto trav_i) {
		auto s_i = trav_i.state(); // contains index in 'i'

		num_t &tmp_i = tmp[s_i];
		num_t &y_i   = y[s_i];

		y_i = alpha * tmp_i + beta * y_i;
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;
	using namespace noarr;

	// problem size
	std::size_t n = N;

	// scalars
	num_t alpha;
	num_t beta;

	// common lengths for dimensions 'i' and 'j'
	auto set_lengths =
		set_length<'i'>(n) ^
		set_length<'j'>(n);

	// data structures
	auto A   = bag(scalar<num_t>() ^ mat_layout ^ set_lengths);
	auto B   = bag(scalar<num_t>() ^ mat_layout ^ set_lengths);
	auto tmp = bag(scalar<num_t>() ^ y_layout   ^ set_lengths); // length N in 'i'
	auto x   = bag(scalar<num_t>() ^ x_layout   ^ set_lengths); // length N in 'j'
	auto y   = bag(scalar<num_t>() ^ y_layout   ^ set_lengths); // length N in 'i'

	// initialize data
	init_array(alpha, beta, A.get_ref(), B.get_ref(), x.get_ref());

	// timing
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_gesummv(alpha, beta,
	               A.get_ref(), B.get_ref(),
	               tmp.get_ref(), x.get_ref(), y.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// optional: print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		serialize_data(std::cerr, y.get_ref() ^ hoist<'i'>());
	}

	// print elapsed time
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
